string[] tables = { "Users", "Circles", "CircleMembers", "Rounds", "Payments", "EkubCategories" };

foreach (var table in tables)
{
    var countCmd = conn.CreateCommand();
    countCmd.CommandText = $"SELECT COUNT(*) FROM \"{table}\"";
    var count = countCmd.ExecuteScalar();
    Console.WriteLine($"\n{'=',-80}");
    Console.WriteLine($"  TABLE: {table}  ({count} rows)");
    Console.WriteLine($"{'=',-80}");

    var cmd = conn.CreateCommand();
    cmd.CommandText = $"SELECT * FROM \"{table}\" LIMIT 30";
    var reader = cmd.ExecuteReader();

    var cols = new string[reader.FieldCount];
    var widths = new int[reader.FieldCount];
    for (int i = 0; i < reader.FieldCount; i++)
    {
        cols[i] = reader.GetName(i);
        widths[i] = Math.Min(cols[i].Length, 20);
    }

    // Read all rows first
    var rows = new List<string[]>();
    while (reader.Read())
    {
        var row = new string[reader.FieldCount];
        for (int i = 0; i < reader.FieldCount; i++)
        {
            var val = reader.IsDBNull(i) ? "NULL" : reader.GetValue(i).ToString()!;
            if (val.Length > 25) val = val[..22] + "...";
            row[i] = val;
            widths[i] = Math.Min(Math.Max(widths[i], val.Length), 25);
        }
        rows.Add(row);
    }

    // Print header
    Console.WriteLine(string.Join(" | ", cols.Select((c, i) => c.PadRight(widths[i]))));
    Console.WriteLine(string.Join("-+-", widths.Select(w => new string('-', w))));

    foreach (var row in rows)
        Console.WriteLine(string.Join(" | ", row.Select((v, i) => v.PadRight(widths[i]))));

    if (rows.Count == 0) Console.WriteLine("  (empty)");
}

conn.Close();
Console.WriteLine("\nDone.");

