/* Payout rotation tracker */
.queue-subtitle { font-size: 12px; color: #888; margin: -8px 0 14px; }
.rotation-track { display: flex; align-items: flex-start; overflow-x: auto; padding: 8px 0 4px; gap: 0; }
.rotation-step { display: flex; flex-direction: column; align-items: center; position: relative; min-width: 64px; }
.step-bubble { width: 40px; height: 40px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700; border: 2px solid #ddd; background: #f5f5f5; color: #999; z-index: 1; }
.rotation-step.done .step-bubble { background: #e8f5e9; border-color: #0F6B2D; color: #0F6B2D; }
.rotation-step.current .step-bubble { background: #fffbea; border-color: #F2B705; color: #F2B705; box-shadow: 0 0 0 4px rgba(242,183,5,0.15); }
.rotation-step.waiting .step-bubble { background: #f5f5f5; border-color: #ddd; color: #bbb; }
.step-line { position: absolute; top: 20px; left: 50%; width: 100%; height: 2px; background: #ddd; z-index: 0; }
.step-line.done-line { background: #0F6B2D; }
.step-icon { font-size: 16px; }
.step-num { font-size: 13px; font-weight: 700; }
.step-name { font-size: 11px; color: #555; margin-top: 6px; text-align: center; max-width: 56px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.step-you { font-size: 10px; color: #0F6B2D; font-weight: 700; margin-top: 2px; }

